typeDefinitions.declaration:
export interface ProductShellSearchResult {
  id: string;
  title: string;
  titleKey?: string;
  meta?: string;
  metaKey?: string;
  href: string;
  selected?: boolean;
}

export interface ShellDropdownProps extends Omit<HTMLAttributes<HTMLDivElement>, "children" | "title" | "id"> {
  /** Id of the drop-down dialog: the aria-controls of the pinned item (ShellPins menuIdOf). */
  id: string;
  /** The pinned group or submenu whose entries the drop-down lists. */
  source: ShellMenuGroup | ShellMenuItem;
  /** Level of the drop-down's own rows: 2 under a pinned group, 3 (the default) under a pinned item. */
  level?: number;
  /** Whether the drop-down is open; closed, nothing is rendered. */
  open: boolean;
  /** Whether opening the drop-down moves focus to its search. Defaults to true. */
  focusOnOpen?: boolean;
  /** Asks to close the drop-down (Esc, a press outside, a choice). */
  onOpenChange?: (open: boolean, reason: ShellLayerCloseReason) => void;
  /** The pinned item; found through its aria-controls when omitted. */
  triggerRef?: RefObject<HTMLElement | null>;
  /** A clipping scroll frame for the cascades. Without it the side follows the viewport. */
  cascadeBoundaryRef?: RefObject<HTMLElement | null>;
  /** The row of the current page. */
  selectedId?: string | null;
  /** Ids of the pinned groups, items and children. */
  pinnedIds?: readonly string[];
  /** Pins or unpins a row; without it the rows have no pin. */
  onPinnedChange?: (id: string, pinned: boolean) => void;
  /** Placeholder of the search; "Search {name}" in the reader's language when omitted. */
  searchPlaceholder?: string;
  /** The search provider, given only this part of the menu; the model is searched when omitted. */
  searchProvider?: ShellMenuSearchProvider;
  /** Language of the copy; the page's own when omitted. */
  locale?: TcrnLocale | string;
  /**
   * Static states for documentation, by row id: data-tcrn-preview-state. A row with a next level
   * marked "open" starts with that level open (from the drop-down's own rows down), as a page
   * rendered on the server shows a drop-down with its cascade.
   */
  previewStates?: Readonly<Record<string, string>>;
  /**
   * The name of the shell the drop-down belongs to, which tells it from another shell's on the same
   * page: the drop-down is named "{landmarkLabel} · {pinned entry}" in the reader's language. Omitted,
   * it is named by the pinned entry alone (TCRN-DS-SUB-184; ProductShell passes its own).
   */
  landmarkLabel?: string;
}

export interface ShellMenuItem {
  /** Stable id: the key of the row in the pin preferences, the selected id and data-pin. */
  id: string;
  /** Visible name; it truncates on one line and is repeated in the title. */
  label: string;
  /** Destination of the row. A row with a next level opens it instead of navigating. */
  href?: string;
  /** Roster icon; the full menu's columns show it, the drop-down and the cascades do not. */
  iconName?: IconName;
  /** The next level. An item's children are the third level, theirs the fourth and last. */
  children?: readonly ShellMenuItem[];
  /**
   * What the entry holds, said with its row to a screen reader (aria-describedby to a
   * .tcrn-sr-only element); nothing is drawn, and without it the row's markup is unchanged.
   */
  description?: string;
  /** Top-strip alignment when pinned (STORY-157). */
  align?: "start" | "end";
  /** External/secondary window link state (STORY-157). */
  external?: boolean;
  /** Role-gated or route-gated disabled state (STORY-157). */
  disabled?: boolean;
  /** Accessible explanation when disabled. */
  disabledReason?: string;
}

export interface ShellMenuGroup {
  id: string;
  label: string;
  /**
   * What the group (a category of the menu) holds, said to a screen reader with its title row in
   * the panel and with its row in the Sheet (aria-describedby to a .tcrn-sr-only element); nothing
   * is drawn, and without it the markup is unchanged.
   */
  description?: string;
  iconName?: IconName;
  /** Top-strip alignment inherited by pinned group/items unless overridden (STORY-157). */
  align?: "start" | "end";
  /** Role-gated or route-gated disabled state (STORY-157). */
  disabled?: boolean;
  disabledReason?: string;
  items: readonly ShellMenuItem[];
}

example.usage:
import type { ComponentProps } from "react";
import { ShellDropdown, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example(props: ComponentProps<typeof ShellDropdown>) {
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <ShellDropdown {...props} />
    </div>
  </>;
}
